new='''const COMMIT_REFERENCE_KINDS = new Set(["commit", "git_commit"]);

/**
 * The journal writes commit links as either `commit` or `git_commit`. Both are the same structured
 * identity; reading only one spelling made a verified version basis look like an open question.
 */
function commitReferenceId(ref: { readonly kind: string; readonly id: string }): string | null {
  return COMMIT_REFERENCE_KINDS.has(ref.kind) ? ref.id : null;
}

function commitReferencesOf(entry: ProjectJournalViewEntry): readonly string[] {
  return Object.freeze(
    [...new Set(entry.entry.relatedRefs.map(commitReferenceId).filter((id): id is string => id !== null))],
  );
}

function uniqueRefs(refs: readonly (string | null | undefined)[]): readonly string[] {
  return Object.freeze([...new Set(refs.filter((ref): ref is string => typeof ref === "string" && ref !== ""))]);
}

/** Preserve the owner's ref spelling and add a normalised commit alias for `explain`. */
function relatedSourceRefs(entry: ProjectJournalViewEntry): readonly string[] {
  return Object.freeze(
    entry.entry.relatedRefs.flatMap((ref) => {
      const commit = commitReferenceId(ref);
      return commit === null ? [`${ref.kind}:${ref.id}`] : [`${ref.kind}:${ref.id}`, `commit:${commit}`];
    }),
  );
}

function journalSourceRefs(entry: ProjectJournalViewEntry): readonly string[] {
  return uniqueRefs([
    `journal:${entry.entry.entryId}`,
    entry.entry.provenance,
    ...relatedSourceRefs(entry),
  ]);
}

function recordedReference(entry: ProjectJournalViewEntry): boolean {
  if (entry.entry.kind !== "REFERENCE_NOTE") return false;
  const provenance = entry.entry.provenance;
  if (provenance.startsWith("episode:") || provenance.startsWith("relay:")) return true;
  return commitReferencesOf(entry).length > 0;
