/**
 * An episode conclusion is a first-class journal record. It must stay explainable after the pulse
 * moves on, and its artifact provenance is the bridge from the old judgement to the bytes/commits it
 * actually delivered. This projects that record; it does not turn the judgement into acceptance.
 */
function episodeConclusionItems(
  entries: readonly ProjectJournalViewEntry[],
  basis: ContinuityBasis,
): readonly ContinuityItem[] {
  const items: ContinuityItem[] = [];
  for (const entry of entries) {
    const conclusion = parseEpisodeConclusion(entry.entry.body);
    if (conclusion === null) continue;
    const artifacts = conclusion.check.artifacts ?? [];
    const artifactLines =
      artifacts.length === 0
        ? "(no artifact provenance recorded)"
        : artifacts
            .map(
              (state) =>
                `- ${state.path}: ${state.commit === null || state.commit === undefined ? "no commit recorded" : `commit ${state.commit}`}` +
                ` (${state.source ?? "source unrecorded"}; ${state.detail})`,
            )
            .join("\\n");
    const deliveredCommits = artifacts
      .map((state) => state.commit)
      .filter((commit): commit is string => typeof commit === "string" && commit !== "");
    items.push(
      item({
        id: `episode:${conclusion.conclusionId}`,
        standing: "AGENT_INTERPRETATION",
        title: `Episode conclusion: ${conclusion.intent}`,
        detail:
          `${conclusion.statement}\\n\\n` +
          `Recorded ${conclusion.recordedAt} at project revision ${String(conclusion.basis.projectRevision)}, ` +
          `head ${conclusion.basis.headCommit}.\\n` +
          `Journal entry: journal:${entry.entry.entryId}\\n` +
          `Delivered artifact versions:\\n${artifactLines}\\n\\n` +
          "This is an advisory episode judgement, not acceptance or a promotion.",
        sourceRefs: uniqueRefs([
          `episode:${conclusion.conclusionId}`,
          ...journalSourceRefs(entry),
          ...deliveredCommits.map((commit) => `commit:${commit}`),
          ...conclusion.evidenceRefs,
        ]),
        basis,
        applicability: "a recorded judgement at its stated basis; it accepts nothing by itself",
        adoptionBasis: "recorded in the project journal as an episode conclusion",
        reopenConditions: [
          "a later project revision, head move, or basis-bearing journal record",
          "operator acceptance, rejection, or a superseding conclusion",
        ],
      }),
    );
  }
  return Object.freeze(items);
}

/**
 * A commit-linked REFERENCE_NOTE is a recorded observation, not an unresolved question. Keeping it
 * separately explainable preserves the verifier's source while removing it from the to-do list.
 */
function referenceItems(
  entries: readonly ProjectJournalViewEntry[],
  basis: ContinuityBasis,
): readonly ContinuityItem[] {
  const items: ContinuityItem[] = [];
  for (const entry of entries) {
    if (entry.entry.kind !== "REFERENCE_NOTE") continue;
    if (parseEpisodeConclusion(entry.entry.body) !== null) continue;
    const commits = commitReferencesOf(entry);
    if (commits.length === 0) continue;
    const namesCurrentHead = commits.includes(basis.headCommit);
    items.push(
      item({
        id: `journal:${entry.entry.entryId}`,
        standing: "OBSERVED_SOURCE",
        title: entry.entry.title,
        detail: entry.entry.body,
        sourceRefs: journalSourceRefs(entry),
        basis,
        applicability: "a recorded reference note; it does not accept a result or advance the project head",
        adoptionBasis: "recorded in the project journal against the named commit(s)",
        currentApplicability: namesCurrentHead ? "APPLICABLE" : "UNKNOWN",
        applicabilityBasis: namesCurrentHead
          ? `the reference names the current canonical head ${basis.headCommit}`
          : `the reference names ${commits.map((commit) => commit.slice(0, 12)).join(", ")}; its current applicability is not established by the note alone`,
        reopenConditions: ["new evidence, a later accepted revision, or an operator decision"],
      }),
    );
  }
  return Object.freeze(items);
}

/** The current canonical version, including a direct-basis advance that has no promotion fact. */
function acceptedVersionItem(
  ir: ProjectIr,
  status: ReturnType<ContinuityInput["work"]["status"]>,
  basis: ContinuityBasis,
  entries: readonly ProjectJournalViewEntry[],
): ContinuityItem {
  const references = entries.filter((entry) => commitReferencesOf(entry).includes(status.headCommit));
  return item({
    id: `version:${status.headCommit}`,
    standing: "ACCEPTED_FOR_PURPOSE",
    title: `Current accepted project version ${status.headCommit.slice(0, 12)}`,
    detail:
      `The canonical ProjectIR revision ${String(ir.revision)} holds head ${status.headCommit}. ` +
      (references.length === 0
        ? "No journal reference names this head; the canonical ProjectIR head is the source."
        : `Journal references naming this head: ${references.map((entry) => `journal:${entry.entry.entryId}`).join(", ")}.`) +
      " This projection is a read of the head owned by Work; it creates no promotion.",
    sourceRefs: uniqueRefs([
      `commit:${status.headCommit}`,
      `revision:${String(ir.revision)}`,
      ...references.map((entry) => `journal:${entry.entry.entryId}`),
    ]),
    basis,
    applicability: "the version the project currently stands on",
    adoptionBasis: "the current canonical ProjectIR head owned by Work",
    currentApplicability: "APPLICABLE",
    applicabilityBasis: `the canonical head at project revision ${String(ir.revision)}`,
    reopenConditions: ["a later accepted revision that moves the canonical head"],
  });
}
